const missing=state.stations.filter(s=>!current.some(r=>r.station===s));$('guide').textContent=(state.view==='trend'?'Come leggere: passa sui punti per data e risultato originale. I triangoli indicano valori sotto quantificazione; i punti cerchiati in rosso sono fuori soglia. ':state.view==='seasonal'?'Come leggere: ogni punto è una media mensile; il numero di osservazioni può variare tra mesi e stazioni. ':'Come leggere: le statistiche usano le osservazioni disponibili, che possono differire tra stazioni. ')+(missing.length?`${missing.join(', ')}: nessuna misurazione disponibile. `:'')+(s.below?`Valori < LOQ: ${methodNames[state.method]}.`:'');
