function renderThresholdNote(t,lines,y){const outside=y?lines.filter(l=>l.value>y.max||l.value<y.min):[];$('thresholdNote').textContent=!t?'':`Soglia di riferimento${t.star?' *':''}: ${thresholdText(t)}${lines.length?' (linea rossa tratteggiata).':'.'} ${t.note?t.note+' ':''}${outside.length?`La soglia è fuori dalla scala del grafico${outside.some(l=>l.value>y.max)?': i valori rappresentati sono tutti inferiori':''}. Attiva «Includi soglia nella scala» per visualizzarla.`:''}`;}
