$('search').addEventListener('input',e=>populate(e.target.value));$('substanceSelect').addEventListener('change',e=>{state.param=e.target.value;update();});$('year').addEventListener('change',e=>{state.year=e.target.value;update();});$('method').addEventListener('change',e=>{state.method=e.target.value;update();});$('log').addEventListener('change',()=>draw(unitFor(state.param,records)));$('fit').addEventListener('change',()=>draw(unitFor(state.param,records)));
