$('reset').addEventListener('click',()=>{Object.assign(state,{param:defaultParam,year:'all',method:'half',stations:['S1','S2'],view:'trend'});fitParam=null;$('search').value='';$('year').value='all';$('method').value='half';$('log').checked=false;populate();update();});$('prev').onclick=()=>{page--;renderRows();};$('next').onclick=()=>{page++;renderRows();};$('download').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv(current,state.method,thresholds)],{type:'text/csv;charset=utf-8'}));a.href=url;a.download=`galeria-${state.param.replace(/[^a-z0-9]+/gi,'-')}-${state.year}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const dialog=$('infoDialog');let previousFocus;function openInfo(){previousFocus=document.activeElement;dialog.showModal();document.body.style.overflow='hidden';}function closeInfo(){dialog.close();}['info','sources'].forEach(id=>$(id).onclick=openInfo);$('closeInfo').onclick=closeInfo;dialog.addEventListener('close',()=>{document.body.style.overflow='';previousFocus?.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeInfo();}});
async function init(){try{const response=await fetch('data.json');if(!response.ok)throw Error('data');const data=await response.json();records=data.records;thresholds=data.thresholds;const groupOrder=data.groups||[];params=[...new Set(records.map(r=>r.param))].sort((a,b)=>groupOrder.indexOf(thresholds[a]?.group)-groupOrder.indexOf(thresholds[b]?.group)||a.localeCompare(b,'it'));const q=new URLSearchParams(location.search);if(params.includes(q.get('param')))state.param=q.get('param');if(['all','2020','2021','2022','2023','2024','2025'].includes(q.get('anno')))state.year=q.get('anno');if(Object.hasOwn(methodNames,q.get('metodo')))state.method=q.get('metodo');if(Object.hasOwn(views,q.get('vista')))state.view=q.get('vista');const st=q.get('stazioni')?.split(',').filter(s=>stations.includes(s));if(st?.length)state.stations=[...new Set(st)];$('year').value=state.year;$('method').value=state.method;populate();ready=true;$('status').textContent='';update();registerTools();if(location.hash==='#info')openInfo();}catch(e){$('status').textContent='Impossibile caricare i dati. Ricarica la pagina per riprovare.';console.error(e);}}
function registerTools(){if(!document.modelContext?.registerTool)return;try{Promise.resolve(document.modelContext.registerTool({name:'filter_galeria',description:'Imposta parametro e anno nei filtri visibili della dashboard del Fosso Galeria.',inputSchema:{type:'object',properties:{parametro:{type:'string'},anno:{type:'string',enum:['all','2020','2021','2022','2023','2024','2025']}},required:['parametro','anno'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||!params.includes(input.parametro)||!['all','2020','2021','2022','2023','2024','2025'].includes(input.anno))throw Error('Parametro o anno non valido');state.param=input.parametro;state.year=input.anno;$('search').value='';populate();$('year').value=state.year;update();return {parametro:state.param,anno:state.year,...summarized(current,state.method),soglia:thresholdText(thresholds[state.param]),fuori_soglia:compliance(current,thresholds[state.param])};}})).catch(()=>{});}catch{}}
init();
